/* ===== 学生端逻辑 ===== */
(function () {
  // 课堂音效（base64 内嵌）；播放失败静默忽略，不阻塞任何作答逻辑
  const AUDIO_READY_GO = 'data:audio/mpeg;base64,';
  const AUDIO_DING_DONG = 'data:audio/mpeg;base64,';
  function playAudio(b64) {
    try {
      if (!b64) return;
      const a = new Audio(b64);
      const p = a.play();
      if (p && typeof p.catch === 'function') p.catch(() => {});
    } catch (e) { /* 自动播放被拦截等情况忽略 */ }
  }

  let config = null;   // {version, config}
  let state = null;    // gated 状态
  let me = null;       // {sid, name, group}
  let meSubs = [];     // 本人提交
  const view = {};     // 各 tab 布局
  let current = 'pre'; // 当前 tab
  let praSubmitReady = null; // 课堂题提交回调
  let lastGate = null; // 上一次缓存的 gate（用于检测"发布方向"的变化，避免轮询反复打断）
  let gateBaselineReady = false; // 首次进入建立基线后才允许自动跳转
  let pendingFocusPra = false;   // 切到课堂练习后需滚动定位到最新题
  let selfPicked = null; // 自我评价当前选中（未提交）的星级 code
  let selfBusy = false;  // 自我评价提交后“正在生成”阶段，避免轮询重渲染打断
  let entered = false;   // 进入守卫：自动恢复身份 + 手动进入都只初始化一次
  let pollTimer = null;  // 轮询定时器（全局唯一）
  let hbTimer = null;    // 心跳定时器（全局唯一）
  // 自适应轮询节奏（20261016 优化一）：常规空闲 5s；gate 变化/作业发布后 15s 活跃窗口内 1.5s；页面隐藏 10s
  const POLL_IDLE_MS = 5000;
  const POLL_ACTIVE_MS = 1500;
  const POLL_HIDDEN_MS = 10000;
  const POLL_ACTIVE_WINDOW_MS = 15000;
  const GATE_KEYS = ['praOpen', 'preOpen', 'selfOpen', 'feixiangOpen', 'goldOpen', 'kiviOpen'];
  let pollActiveUntil = 0;  // 活跃窗口截止时间戳（0=不在窗口内）
  let loadInFlight = false; // loadAll 防重入（自调度链与回前台立即刷新叠加时只跑一次）
  let lastLockSig = null; // 锁标签名：仅当锁定布尔值真正变化才更新锁标
  let lastViewSig = null; // 当前视图签名：无变化则不重绘，保护正在作答的内容
  let hwGenerating = false; // 老师发布作业瞬间在线的学生：先显示“小奇生成中”过渡（仅本次会话）
  let hwGenAt = 0;        // 进入过渡的时间戳
  let hwGenTimer = null;  // 过渡结束自动重绘的定时器（全局唯一）

  // 课堂练习音效去重：记录已播过提示音的题号（题目切换后再次达到条件可重播）
  let lastPlayedPraIdx = null;   // Ready Go：null=尚未建立基线
  let lastDingDongPraIdx = null; // 叮咚：全班交齐后播一次

  // 草稿
  function draftKey(k) { return me ? `he_${k}_${me.sid}` : `he_${k}`; }
  function loadDraft(k) { try { return JSON.parse(localStorage.getItem(draftKey(k))) || {}; } catch (e) { return {}; } }
  function saveDraft(k, obj) { localStorage.setItem(draftKey(k), JSON.stringify(obj)); }

  // 老师一键清空（resetEpoch 变化）→ 清除本机全部草稿/自评缓存，保留身份 he_me
  // 首次进入仅记录基线，绝不误删
  function syncResetEpoch(s) {
    const epoch = s && s.resetEpoch;
    if (!epoch) return;
    const cur = String(epoch);
    let prev = null;
    try { prev = localStorage.getItem('he_resetEpoch'); } catch (e) { return; }
    if (prev === cur) return;                      // 未发生新一轮清空
    if (prev === null) {                           // 首次进入：只记基线
      try { localStorage.setItem('he_resetEpoch', cur); } catch (e) {}
      return;
    }
    try {
      const drop = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.indexOf('he_') === 0 && k !== 'he_me' && k !== 'he_resetEpoch') drop.push(k);
      }
      drop.forEach(k => localStorage.removeItem(k));
      localStorage.setItem('he_resetEpoch', cur);
    } catch (e) {}
    lastViewSig = null; // 草稿已变，强制重绘当前视图
    toast('老师已重置课堂，本机草稿已清空');
  }

  const $ = (id) => document.getElementById(id);

  function init() {
    loadConfig();
  }

  async function loadConfig() {
    try {
      const r = await apiGet('/api/config');
      config = r;
      bindStudentId();   // roster 就绪后再允许校验
      restoreIdentity(); // 自动恢复身份
    } catch (e) {
      if (location.protocol === 'file:') {
        toast('请用本地服务器打开：先运行 serve.py，再访问 http://127.0.0.1:8080/');
      } else {
        toast('加载班级配置失败：请确认本地服务器(serve.py)已启动');
      }
      console.error('loadConfig failed:', e);
    }
  }

  // ---- 登录：输入学号 ----
  function showIdErr(msg) {
    const el = $('studentIdErr');
    el.textContent = msg;
    el.style.display = 'block';
  }
  function hideIdErr() {
    const el = $('studentIdErr');
    el.textContent = '';
    el.style.display = 'none';
  }

  function tryEnterStudentId() {
    // config（roster）异步未就绪时给明确提示，不进入
    if (!config || !config.config || !Array.isArray(config.config.roster)) {
      showIdErr('名单还在加载，请稍候再试');
      return;
    }
    const raw = ($('studentIdInput').value || '').trim();
    // 仅接受 1~2 位数字
    if (!/^\d{1,2}$/.test(raw)) {
      showIdErr('学号无效，请输入 01-45 之间的学号');
      return;
    }
    const code = raw.padStart(2, '0'); // 3 -> "03", 30 -> "30"
    const found = config.config.roster.find((r) => String(r[0]) === code);
    if (!found) {
      // 不在名单：提示且不进入、不清空输入
      showIdErr('学号无效，请输入 01-45 之间的学号');
      return;
    }
    hideIdErr();
    me = { sid: code, name: code, group: 1 };
    localStorage.setItem('he_me', JSON.stringify(me));
    renderAfterEnter();
  }

  function bindStudentId() {
    const btn = $('studentIdBtn');
    const input = $('studentIdInput');
    btn.addEventListener('click', tryEnterStudentId);
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); tryEnterStudentId(); }
    });
  }

  // 自动恢复上次身份（名单内才恢复）
  function restoreIdentity() {
    const saved = localStorage.getItem('he_me');
    if (!saved) return;
    try {
      const s = JSON.parse(saved);
      const found = config.config.roster.find((r) => String(r[0]) === String(s.sid));
      if (found) { me = s; renderAfterEnter(); }
    } catch (e) {}
  }

  function renderAfterEnter() {
    if (entered) return; // 已进入：自动恢复身份 + 手动点进入都只初始化一次，杜绝多轮询/多心跳/重复绑定
    entered = true;
    $('enter').classList.add('hidden');
    $('main').classList.remove('hidden');
    $('whoBar').classList.remove('hidden');
    $('whoBar').textContent = "学号：" + me.sid;
    const _lb = $('logoutBtn'); if (_lb) _lb.classList.remove('hidden');
    $('welcomeBar').innerHTML = `欢迎你，<b>${me.name}</b>！今天我们一起来从不同方向观察物体 🌟`;
    $('minionBar').classList.remove('hidden');
    setMinion('小奇提示：先看看屏幕上的图形，从右边的角度想一想它是什么样子～');

    // 心跳（全局唯一）
    apiPost('/api/submit', { type: 'hb', sid: me.sid, name: me.name, group: me.group }).catch(() => {});
    if (!hbTimer) {
      hbTimer = setInterval(() => {
        apiPost('/api/submit', { type: 'hb', sid: me.sid, name: me.name, group: me.group }).catch(() => {});
      }, 8000);
    }

    bindTabs();
    initTopTools();
    padDock();
    // 轮询（全局唯一，setTimeout 自调度：活跃窗口 1.5s / 空闲 5s / 页面隐藏 10s）
    loadAll().then(schedulePoll);
    // 回到前台：立即刷一次再按当前节奏继续；隐藏期间由 pollDelay 自动放宽到 10s（省电降压）
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') loadAll().then(schedulePoll);
    });
  }

  // 三个学习工具链接（飞象老师 / 黄金矿工 为 fbcontent 文档；鸟巢为 kivicube）
  const FEIXIANG_URL = 'https://musk-online.fbcontent.cn/pub-musk-ai-studio/workflow/file/document/U8M3AoyeEsrYvY87SEnVTU.html?watermarkTheme=main';
  const GOLD_MINER_URL = '/hjkg/';
  const KIVI_URL = 'https://www.kivicube.com/scenes/Lp5JsVnMFWQdeLWg2eUddYznpRe03B1W';
  let gmPostedScore = null; // 游戏 postMessage 自动拿到的积分（best effort）

  // 退出登录 + 底部三工具栏（仅进入后绑定一次）
  let gmOpened = false; // 黄金矿工弹窗当前是否已打开，避免重复上报
  function initTopTools() {
    const logoutBtn = $('logoutBtn');
    if (logoutBtn && !logoutBtn._bound) {
      logoutBtn._bound = true;
      logoutBtn.addEventListener('click', () => {
        localStorage.removeItem('he_me');
        localStorage.removeItem('he_draft');
        localStorage.removeItem('he_media');
        localStorage.removeItem('he_selfEval');
        location.href = '/';
      });
    }
    // 三个工具均受教师发布开关控制；未发布只提示、不打开
    bindFrameLoading('fxFrame', 'fxLoading');
    bindFrameLoading('kvFrame', 'kvLoading');
    bindFrameLoading('gmFrame', 'gmLoading');
    $('toolFeixiang').onclick = async () => {
      const g = await readGate();
      if (!g.feixiangOpen) { topNotice('老师还没有开放飞象老师，请稍候'); return; }
      $('fxMask').classList.remove('hidden');
      showFrameLoading('fxLoading');
      $('fxFrame').src = FEIXIANG_URL;
      padDock();
    };
    $('toolKivicube').onclick = async () => {
      const g = await readGate();
      if (!g.kiviOpen) { topNotice('老师还没有开放鸟巢，请稍候'); return; }
      $('kvMask').classList.remove('hidden');
      showFrameLoading('kvLoading');
      $('kvFrame').src = KIVI_URL;
      padDock();
    };
    $('toolGoldMiner').onclick = async () => {
      if (gmOpened) return;
      const g = await readGate();
      if (!g.goldOpen) { topNotice('老师还没有开放黄金矿工，请稍候'); return; }
      gmOpened = true;
      gmPostedScore = null;
      apiPost('/api/submit', { type: 'gold_miner_open', sid: me.sid, name: me.name, group: me.group }).catch(() => {});
      const mask = $('gmMask');
      mask.classList.remove('hidden');
      const iframe = $('gmFrame');
      showFrameLoading('gmLoading');
      iframe.src = GOLD_MINER_URL;
      padDock();
    };
    $('gmClose').onclick = (ev) => {
      if (ev) ev.preventDefault();
      // 不再手动登记积分：点关闭直接关闭（自动识别到积分则已在消息监听中无感上报）
      finalizeGoldClose();
    };
    $('fxClose').onclick = (ev) => {
      if (ev) ev.preventDefault();
      $('fxMask').classList.add('hidden');
      $('fxFrame').src = 'about:blank';
    };
    $('kvClose').onclick = (ev) => {
      if (ev) ev.preventDefault();
      $('kvMask').classList.add('hidden');
      $('kvFrame').src = 'about:blank';
    };
    bindGoldMessage();
  }

  // 工具弹层加载提示（20261016 优化二）：打开时显示；iframe load 后隐藏；12 秒未 load 兜底自动隐藏，避免卡死
  const frameLoadTimers = {};
  function showFrameLoading(loadingId) {
    const ld = $(loadingId);
    if (!ld) return;
    ld.classList.remove('hidden');
    if (frameLoadTimers[loadingId]) clearTimeout(frameLoadTimers[loadingId]);
    frameLoadTimers[loadingId] = setTimeout(() => {
      ld.classList.add('hidden'); // 兜底：第三方迟迟未触发 load 也隐藏
      frameLoadTimers[loadingId] = null;
    }, 12000);
  }
  function bindFrameLoading(frameId, loadingId) {
    const f = $(frameId);
    if (!f || f._loadingBound) return;
    f._loadingBound = true;
    f.addEventListener('load', () => {
      const ld = $(loadingId);
      if (ld) ld.classList.add('hidden');
      if (frameLoadTimers[loadingId]) { clearTimeout(frameLoadTimers[loadingId]); frameLoadTimers[loadingId] = null; }
    });
  }

  // 实时读取一次 gate（缺字段兼容为 false）
  async function readGate() {
    try {
      const s = await apiGet('/api/state');
      const g = s.gate || {};
      return {
        feixiangOpen: !!g.feixiangOpen,
        goldOpen: !!g.goldOpen,
        kiviOpen: !!g.kiviOpen,
      };
    } catch (e) {
      return { feixiangOpen: false, goldOpen: false, kiviOpen: false };
    }
  }

  function finalizeGoldClose() {
    gmOpened = false;
    const mask = $('gmMask');
    const iframe = $('gmFrame');
    mask.classList.add('hidden');
    iframe.src = 'about:blank';
    gmPostedScore = null;
    padDock();
  }

  // 跨域第三方游戏：监听 postMessage，尽力自动记录积分（全自动、学生无感、不弹窗）
  function bindGoldMessage() {
    window.addEventListener('message', (ev) => {
      if (!gmOpened) return;
      let d = ev.data;
      if (d == null) return;
      if (typeof d === 'string') {
        const t = d.trim();
        if (/^\d+(\.\d+)?$/.test(t)) { reportAutoScore(Number(t)); return; }
        try { d = JSON.parse(t); } catch (e) { return; }
      }
      if (typeof d === 'number') {
        if (!Number.isNaN(d)) reportAutoScore(d);
        return;
      }
      if (typeof d === 'object') {
        let v = null;
        if (d.score != null) v = d.score;
        else if (d.points != null) v = d.points;
        else if (d.grade != null) v = d.grade;
        else if (/score|point|grade|gold/i.test(String(d.type || '')) && d.value != null) v = d.value;
        if (v !== null && v !== '' && !Number.isNaN(Number(v))) reportAutoScore(Number(v));
      }
    });
  }

  // 自动识别到游戏积分 → 无感上报一次（best effort：失败静默，收不到就不报）
  function reportAutoScore(v) {
    if (!me) return;
    gmPostedScore = v;
    apiPost('/api/submit', {
      type: 'gold_miner_done', sid: me.sid, name: me.name, group: me.group, score: v,
    }).catch(() => {});
  }

  // 底部固定容器高度 → body 底部留白，保证最后的内容能滚出、不被遮挡
  function padDock() {
    const dock = $('bottomDock');
    if (!dock) return;
    const h = dock.offsetHeight;
    if (h > 0) document.body.style.paddingBottom = h + 'px';
  }
  window.addEventListener('resize', padDock);
  window.addEventListener('orientationchange', () => setTimeout(padDock, 150));

  function setMinion(t, b) {
    $('minionText').innerHTML = t + (b ? `<br><b>${b}</b>` : '');
  }

  function bindTabs() {
    [...document.querySelectorAll('.tab')].forEach((tab) => {
      tab.addEventListener('click', () => switchTab(tab.dataset.tab));
    });
  }

  function switchTab(t) {
    current = t;
    [...document.querySelectorAll('.tab')].forEach((tab) => tab.classList.toggle('active', tab.dataset.tab === t));
    ['pre', 'pra', 'self', 'hw'].forEach((k) => {
      $('view-' + k).classList.toggle('hidden', k !== t);
    });
    hideSubmitBar();
    if (t === 'pre') renderPre();
    else if (t === 'pra') renderPra();
    else if (t === 'self') renderSelf();
    else renderHw();
  }

  // 自适应轮询（20261016 优化一）：setTimeout 自调度，全局只有一个轮询循环
  function pollDelay() {
    if (document.visibilityState === 'hidden') return POLL_HIDDEN_MS;
    return Date.now() < pollActiveUntil ? POLL_ACTIVE_MS : POLL_IDLE_MS;
  }
  function schedulePoll() {
    if (pollTimer) { clearTimeout(pollTimer); pollTimer = null; }
    pollTimer = setTimeout(async () => {
      pollTimer = null;
      await loadAll();
      schedulePoll();
    }, pollDelay());
  }

  async function loadAll() {
    if (loadInFlight) return; // 防重入：自调度链与 visibilitychange 立即刷新叠加时只跑一次
    loadInFlight = true;
    try {
      // state 与本人提交记录并行拉取（互不依赖），缩短单次刷新耗时
      const [s] = await Promise.all([apiGet('/api/state'), fetchMySubs()]);
      const prevGate = lastGate;
      const prevHwPublished = state ? !!state.hwPublished : null; // 上一帧发布态（首帧为 null）
      state = s;
      // 作业发布上升沿（false→true）：仅本次页面会话内、且学生当时开着页面才触发“小奇生成中”过渡；
      // 刷新页面/晚进入（首帧即 true）不触发；老师收回再发布（false→true）可再次触发
      if (prevHwPublished === false && s.hwPublished === true) {
        hwGenerating = true;
        hwGenAt = Date.now();
        pollActiveUntil = Date.now() + POLL_ACTIVE_WINDOW_MS; // 发布后进入活跃轮询窗口
        // 立即重取一次 state，确保 hwDraft 已随发布事务就绪
        try { state = await apiGet('/api/state'); } catch (e2) { /* 沿用当前 state */ }
      }
      // gate 任何开关变化（逐题发布/收回、preOpen/selfOpen、飞象/鸟巢/黄金矿工开关）→ 15 秒活跃轮询窗口
      if (prevGate && s.gate && GATE_KEYS.some((k) => prevGate[k] !== s.gate[k])) {
        pollActiveUntil = Date.now() + POLL_ACTIVE_WINDOW_MS;
      }
      syncResetEpoch(s);

      // 锁标：仅当锁定布尔值真正变化才更新一次（避免每 5 秒反复 toggle 造成闪烁）
      const clk = lockSigOf();
      if (clk !== lastLockSig) { updateLocks(); lastLockSig = clk; }

      // 仍在名单页（防御），不向下处理
      if (document.getElementById('enter') && !document.getElementById('enter').classList.contains('hidden')) {
        lastGate = s.gate ? { ...s.gate } : null;
        return;
      }

      // 发布提示：非阻塞小提示，“绝不”切换当前 Tab
      maybeHintGate(prevGate, s.gate);
      lastGate = s.gate ? { ...s.gate } : null;
      gateBaselineReady = true;

      // 课堂练习音效（作业区/其它 tab 不受影响）
      maybePlayPraAudio(s.gate ? s.gate.praOpen : -1);

      // 视图：仅内容确有变化时才重绘当前 Tab，无变化不动 DOM（保护作答/草稿/当前 Tab）
      const cv = viewSigOf();
      if (cv !== lastViewSig) { refreshCurrentView(); lastViewSig = cv; }
    } catch (e) { /* 网络抖动忽略 */ }
    finally { loadInFlight = false; }
  }

  // 锁标签名（仅锁定布尔值），变化驱动锁标更新
  function lockSigOf() {
    const g = state && state.gate ? state.gate : {};
    return [!!g.preOpen, (typeof g.praOpen === 'number' ? g.praOpen : -1), !!g.selfOpen, !!(state && state.hwPublished)].join('|');
  }
  // 视图签名：锁定状态 + 本人“有效提交”记录
  // 注意刻意排除 type==='media' 的附属数据记录：
  // media 题的完成以 submit_pra(pra/q5) 为准；media_data 仅是上传的图片/音频数据，
  // 若计入签名，拍照上传成功后 5 秒轮询会因签名变化触发 renderPra 重绘，
  // 造成视图跳回默认题（如第3题）/滚动位置丢失。
  function viewSigOf() {
    const my = meSubs
      .filter((s) => s.type !== 'media')
      .map((s) => s.id)
      .join(',');
    // 作业抽题结果变化（换一批/重新发布）也要触发重绘，旧草稿按签名失效
    const hwD = state && state.hwDraft
      ? ['A', 'B', 'C'].map((L) => (Array.isArray(state.hwDraft[L]) ? state.hwDraft[L].join('.') : '')).join('|')
      : '';
    return lockSigOf() + '#' + my + '@' + hwD;
  }
  // 仅重绘“当前所在 Tab”的视图，不切换 Tab
  function refreshCurrentView() {
    if (document.getElementById('enter') && !document.getElementById('enter').classList.contains('hidden')) return;
    if (current === 'pre') { if (state.gate.preOpen) renderPre(); else renderWait('pre'); }
    else if (current === 'pra') renderPra();
    else if (current === 'self') { if (!selfBusy) renderSelf(); }
    else if (current === 'hw') { if (state.hwPublished) renderHw(); else renderWait('hw'); }
  }

  // 仅在"确实发生变化、且为发布方向"时弹一条非阻塞小提示；绝不自动切换 Tab、不抢焦点
  function maybeHintGate(prev, gate) {
    if (!gate || !gateBaselineReady) return;
    const oldPra = (prev && typeof prev.praOpen === 'number') ? prev.praOpen : -1;
    const newPra = (typeof gate.praOpen === 'number') ? gate.praOpen : -1;
    // 课堂练习：发布了更新的题
    if (newPra > oldPra) {
      topNotice('老师发布了新题目，可点击「课堂练习」查看');
      return;
    }
    const oldPre = prev ? !!prev.preOpen : false;
    const oldSelf = prev ? !!prev.selfOpen : false;
    if (!oldPre && gate.preOpen) {
      topNotice('课前小测已发布');
      return;
    }
    if (!oldSelf && gate.selfOpen) {
      topNotice('自我评价已发布，可点击「自我评价」查看');
    }
  }

  // 顶部短暂提示
  let topNoticeTimer = null;
  function topNotice(msg) {
    let el = document.getElementById('topNotice');
    if (!el) {
      el = document.createElement('div');
      el.id = 'topNotice';
      el.className = 'top-notice';
      document.body.appendChild(el);
    }
    el.textContent = msg;
    el.classList.add('show');
    clearTimeout(topNoticeTimer);
    topNoticeTimer = setTimeout(() => el.classList.remove('show'), 2600);
  }

  // 课堂练习提示音：
  // 1) 老师发布一道题（-1→≥0）或切换到另一道题时播一次 Ready Go；回到 -1 重置；首次进入只建基线不播。
  // 2) 当前题全班（praStat.answered=名单人数）都交卷时播一次叮咚；题目切换后允许再次触发。
  function maybePlayPraAudio(praIdx) {
    // Ready Go
    if (lastPlayedPraIdx === null) {
      lastPlayedPraIdx = praIdx;
    } else if (praIdx !== lastPlayedPraIdx) {
      if (praIdx >= 0) playAudio(AUDIO_READY_GO);
      lastPlayedPraIdx = praIdx;
    }
    // 叮咚：全班交齐（服务端 /api/state 按当前题统计去重提交人数）
    const st = state && state.praStat;
    const need = st && typeof st.total === 'number' ? st.total : 0;
    if (praIdx >= 0 && st && need > 0 && st.answered >= need) {
      if (lastDingDongPraIdx !== praIdx) {
        playAudio(AUDIO_DING_DONG);
        lastDingDongPraIdx = praIdx;
      }
    } else if (praIdx < 0) {
      lastDingDongPraIdx = null;
    }
  }

  async function fetchMySubs() {
    try {
      // 只拉取本人提交（服务端按 sid 过滤，减小 payload；?sid= 不影响教师端全量查询）
      const r = await apiGet('/api/submissions?sid=' + encodeURIComponent(me.sid));
      meSubs = r.submissions.filter((x) => x.sid === me.sid);
    } catch (e) { meSubs = []; }
  }

  function updateLocks() {
    if (!state) return;
    const lockEl = (t) => document.querySelector(`.tab[data-tab="${t}"] .lock`);
    preOpen = !!state.gate.preOpen;
    praOpenIdx = (typeof state.gate.praOpen === 'number' && state.gate.praOpen >= 0) ? state.gate.praOpen : -1;
    selfOpen = !!state.gate.selfOpen;
    hwOpen = !!state.hwPublished;

    setLock('pre', preOpen);
    setLock('pra', praOpenIdx >= 0);
    setLock('self', selfOpen);
    setLock('hw', hwOpen);
  }
  let preOpen = false, selfOpen = false, hwOpen = false, praOpenIdx = -1;
  function setLock(t, open) {
    const tab = document.querySelector(`.tab[data-tab="${t}"]`);
    tab.classList.toggle('locked', !open);
    tab.querySelector('.lock').textContent = open ? '' : '🔒';
  }

  function renderWait(t) {
    const names = { pre: '课前小测', pra: '课堂练习', self: '自我评价', hw: '课后作业' };
    const el = document.getElementById('view-' + t);
    if (el) el.innerHTML = `
      <div class="card wait">
        <div class="big">🔒</div>
        <p><b>${names[t]}</b> 尚未开放<br/>请耐心等待老师发布～</p>
      </div>`;
  }

  /* ---------- 课前小测 ---------- */
  function renderPre() {
    const root = $('view-pre');
    if (!state || !state.gate.preOpen) { renderWait('pre'); return; }
    const draft = loadDraft('pre');
    const root2 = root;
    let html = `<div class="card"><h2>📝 课前小测</h2><div class="sub">整组题目作答完成后，点底部「提交」一次性交卷。</div>`;
    config.config.pre.forEach((q, i) => {
      html += `<div class="q-banner">第 ${i + 1} 题</div><div class="q-text">${q.text}</div>`;
      if (q.scene) html += `<img class="q-img" src="${q.scene}" alt="scene"/>`;
      // 选项为图片
      html += `<div class="opts v3" id="pre-opt-${q.id}">`;
      q.options.forEach((o, idx) => {
        const isImg = typeof o === 'string' && (o.indexOf('data:') === 0 || o.indexOf('/assets/img/') === 0);
        const sel = draft[q.id] === idx;
        html += `<div class="opt ${sel ? 'sel' : ''}" data-v="${idx}" data-q="${q.id}">
          ${isImg ? `<img src="${o}"/>` : `<div class="txt">${o}</div>`}</div>`;
      });
      html += `</div>`;
    });
    html += `</div>`;
    root2.innerHTML = html;

    root2.querySelectorAll('.opt').forEach((o) => {
      o.addEventListener('click', () => {
        const qid = o.dataset.q, v = Number(o.dataset.v);
        const d = loadDraft('pre');
        d[qid] = v;
        saveDraft('pre', d);
        root2.querySelectorAll(`.opt[data-q="${qid}"]`).forEach((x) => x.classList.toggle('sel', Number(x.dataset.v) === v));
        checkPreAllDone();
      });
    });
    checkPreAllDone();
  }

  let preAllDone = false;
  function checkPreAllDone() {
    if (!config) return;
    const draft = loadDraft('pre');
    preAllDone = config.config.pre.every((q) => draft[q.id] !== undefined && draft[q.id] !== null);
    if (current === 'pre') refreshSubmitBar('pre');
  }

  function refreshSubmitBar(t) {
    if (t === 'pre') {
      if (preAllDone) {
        showSubmitBar('课前小测已准备好，点击下方提交交卷', '提交', submitPre);
      } else hideSubmitBar();
    } else if (t === 'pra') {
      if (praSubmitReady) {
        showSubmitBar('作答完成，点击提交本题', '提交本题', praSubmitReady);
      } else hideSubmitBar();
    } else if (t === 'hw') {
      if (hwAllDone) {
        showSubmitBar(`${hwCurrent.qs.length} 题均已作答，点击下方提交作业`, '提交作业', submitHw);
      } else hideSubmitBar();
    } else hideSubmitBar();
  }

  async function submitPre() {
    const draft = loadDraft('pre');
    const answers = config.config.pre.map((q) => ({ qid: q.id, v: draft[q.id] }));
    try {
      await apiPost('/api/submit', { type: 'submit_pre', sid: me.sid, name: me.name, group: me.group, answers });
      toast('✅ 课前小测已提交');
      hideSubmitBar();
      await fetchMySubs();
    } catch (e) { toast('提交失败，请重试'); }
  }

  /* ---------- 课堂练习 ---------- */
  // 提交后按服务端判分随机弹鼓励语（逐字常量，勿改写）
  const PRA_WRONG = [
    '没关系！一次答错很正常，再仔细看一看题目吧！',
    '别灰心，我们再换个角度想一想！',
    '加油，再试试看，小奇相信你可以找到线索！',
  ];
  const PRA_RIGHT = [
    '太棒啦！答案完全正确👍',
    '答对咯，观察得很仔细！',
    '完全正确，你掌握这个知识点啦！',
    '厉害，一下子就找到答案了！',
  ];
  let praiseTimer = null;
  // 居中明显的大弹层：答对绿色系、答错橙色系，停留数秒自动消失（非阻塞）
  function praisePop(msg, ok) {
    let el = document.querySelector('.praise-pop');
    if (!el) { el = document.createElement('div'); el.className = 'praise-pop'; document.body.appendChild(el); }
    el.textContent = msg;
    el.classList.remove('ok', 'no', 'show');
    el.classList.add(ok ? 'ok' : 'no');
    void el.offsetWidth; // 重置过渡动画
    el.classList.add('show');
    clearTimeout(praiseTimer);
    praiseTimer = setTimeout(() => el.classList.remove('show'), 2600);
  }
  function pickPraise(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
  // 本题“已完成（冻结）”判定：计分题须存在答对记录（答错可改了再交）；media 题维持“有提交即完成”
  /* 课堂练习“已改对”本地锁定：pra 重试不入库（服务端只留第一次提交），
     学生改对后用 localStorage(he_ 前缀，随 resetEpoch 一并清除) 记录本题已答对，
     保证答对锁定状态跨轮询/刷新仍生效。 */
  let praPassedCache = null;
  function getPraPassed() {
    if (!me) return {};
    if (!praPassedCache || praPassedCache._sid !== me.sid) {
      let obj = {};
      try { obj = JSON.parse(localStorage.getItem('he_praPassed_' + me.sid) || '{}') || {}; } catch (e) { obj = {}; }
      obj._sid = me.sid;
      praPassedCache = obj;
    }
    return praPassedCache;
  }
  function markPraPassed(qid) {
    const p = getPraPassed();
    if (p[qid]) return;
    p[qid] = true;
    try { localStorage.setItem('he_praPassed_' + me.sid, JSON.stringify(p)); } catch (e) {}
  }

  function praDone(q) {
    if (getPraPassed()[q.id]) return true; // 重试已改对（库里只存第一次，本地记锁定）
    if (q.kind === 'media') return meSubs.some((s) => s.type === 'pra' && s.qid === q.id);
    return meSubs.some((s) => s.type === 'pra' && s.qid === q.id && s.correct === true);
  }

  function renderPra() {
    const root = $('view-pra');
    if (!state || praOpenIdx < 0) { root.innerHTML = waitCard('课堂练习'); return; }
    const q = config.config.practice[praOpenIdx];
    if (!q) { root.innerHTML = waitCard('课堂练习'); return; }
    const draft = loadDraft('pra');
    const done = praDone(q);

    let html = `<div class="card" id="praCard"><h2>🎯 课堂练习 · 第 ${praOpenIdx + 1} 题</h2><div class="sub">${done ? '<span class="done-tick">✅ 已提交 ✓</span>' : '认真观察，完成后提交本题'}</div>`;

    if (q.kind === 'imgchoice') {
      html += `<div class="q-text">${q.text}</div>`;
      if (q.scene) {
        // 三视图合并题：直接展示 scene 图片（如“从三个角度观察”的茶叶罐三视图），不再用 obj/obs
        html += `<div class="q-banner">观察到的三视图：</div>`;
        html += `<img class="q-img" src="${q.scene}" alt="scene"/>`;
      } else {
        if (q.obj) html += `<img class="q-img" src="${q.obj}" alt="obj"/>`;
        html += `<div class="q-banner">观察到的图形：</div>`;
        if (q.obs) html += `<img class="q-img" src="${q.obs}" alt="obs"/>`;
      }
      html += `<div class="opts v3" id="pra-opt-${q.id}">`;
      q.options.forEach((o, idx) => {
        const isImg = typeof o === 'string' && (o.indexOf('data:') === 0 || o.indexOf('/assets/img/') === 0);
        const sel = draft[q.id] != null && Number(draft[q.id]) === idx;
        html += `<div class="opt ${sel ? 'sel' : ''}" data-v="${idx}">
          ${isImg ? `<img src="${o}"/>` : `<div class="txt">${o}</div>`}</div>`;
      });
      html += `</div>`;
    } else if (q.kind === 'match') {
      html += `<div class="q-text">${q.text}</div>`;
      if (q.obj) html += `<img class="q-img" src="${q.obj}" alt="obj"/>`;
      const links = draft[q.id] && typeof draft[q.id] === 'object' ? draft[q.id] : {};
      html += `<div class="q-banner">先点左边图块，再点右边答案完成连线（可重选）</div>`;
      html += `<div class="match" id="match-box-${q.id}">`;
      html += `<svg class="match-svg" id="match-svg-${q.id}"></svg>`;
      html += `<div class="col">
          <div class="label">图块</div>` + q.tiles.map((t) =>
        `<div class="m-item" data-tile="${t.id}" data-label="图块">${
          t.img ? `<img src="${t.img}"/>` : `<div class="txt">${t.label || ''}</div>`}</div>`).join('') + `</div>`;
      html += `<div class="arrow">→</div>`;
      html += `<div class="col">
          <div class="label">观察方向</div>` + q.targets.map((t) =>
        `<div class="m-item" data-target="${t.id}"><div class="txt">${t.label}</div></div>`).join('') + `</div>`;
      html += `</div>`;
    } else if (q.kind === 'media') {
      html += `<div class="q-text">${q.text}</div>`;
      html += `<div class="sub">${q.prompt || ''}</div>`;
      const media = loadMediaDraft(q.id);
      html += `<div class="media-box">
        <div class="media-row">
          <span class="media-btn ${media.img ? 'done' : ''}" id="camBtn">${media.img ? '✅ 已拍照' : '📷 拍照上传'}</span>
          <input type="file" id="camInput" accept="image/*" capture="environment" class="hidden"/>
        </div>
        <div id="camPreviewArea">${media.img ? `<img class="capture-preview" src="${media.img}"/>` : ''}</div>
        <div class="media-row">
          <span class="media-btn ${media.audio ? 'done' : ''}" id="recBtn">${media.audio ? '🔊 已录音' : '🎙️ 录音补充说明'}</span>
        </div>
        <div class="rec-stamp hidden" id="recStamp">● 录音中… 点击停止</div>
        <div id="audioArea">${media.audio ? `<audio controls src="${media.audio}"></audio>` : ''}</div>
      </div>`;
    }
    html += `</div>`;
    root.innerHTML = html;

    if (q.kind === 'imgchoice') {
      let ready = draft[q.id] != null && draft[q.id] !== '';
      root.querySelectorAll('#pra-opt-' + q.id + ' .opt').forEach((o) => {
        o.addEventListener('click', () => {
          if (done) return; // 已提交本题，禁止再作答
          const v = Number(o.dataset.v);
          const d = loadDraft('pra');
          d[q.id] = v; saveDraft('pra', d);
          root.querySelectorAll('#pra-opt-' + q.id + ' .opt').forEach((x) => x.classList.toggle('sel', Number(x.dataset.v) === v));
          if (!done) { praSubmitReady = () => submitPraImg(q); refreshSubmitBar('pra'); }
        });
      });
      if (!done && ready) { praSubmitReady = () => submitPraImg(q); refreshSubmitBar('pra'); }
    } else if (q.kind === 'match') {
      initMatchBox(q, root);
    } else if (q.kind === 'media') {
      initMediaBox(q, root, done);
    }
    if (done) hideSubmitBar();

    // 教师发布新题后自动定位：滚动到题目顶部，让学生立刻看到
    if (pendingFocusPra) {
      pendingFocusPra = false;
      requestAnimationFrame(() => {
        const card = root.querySelector('#praCard');
        const target = card || root.firstElementChild || root;
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    }
  }

  function waitCard(name) {
    return `<div class="card wait"><div class="big">🔒</div><p><b>${name}</b> 尚未开始<br/>请等待老师逐题发布</p></div>`;
  }

  async function submitPraImg(q) {
    const d = loadDraft('pra');
    const v = d[q.id];
    try {
      const r = await apiPost('/api/submit', { type: 'submit_pra', sid: me.sid, name: me.name, group: me.group, qid: q.id, v, duration: 0 });
      await fetchMySubs();
      if (r && r.correct === true) {
        markPraPassed(q.id);
        praisePop(pickPraise(PRA_RIGHT), true); // 答对：表扬 + 冻结本题
        hideSubmitBar();
      } else if (r && r.correct === false) {
        praisePop(pickPraise(PRA_WRONG), false); // 答错：鼓励 + 不冻结，允许改了再交
      } else {
        toast('✅ 已提交本题'); // correct===null（不计分）：维持现状
        hideSubmitBar();
      }
      renderPra();
    } catch (e) { toast('提交失败'); }
  }

  /* 连一连交互：初始完全未连线；明显选中态 + SVG 黑色连线（可重选/重连） */
  function initMatchBox(q, root) {
    const d0 = loadDraft('pra');
    // 连线只取“本学生自己保存的草稿”；首次进入/未作答时为空 {}。
    // 严禁使用题目正确答案 q.answer 预填，也不从上一次渲染残留带入。
    const links = d0[q.id] && typeof d0[q.id] === 'object' ? { ...d0[q.id] } : {};
    // 显式守卫：绝不读取正确答案（q.answer）来初始化任何连线
    void q.answer;
    let picked = null;
    let matchReady = false;
    const box = root.querySelector('#match-box-' + q.id);
    const svg = root.querySelector('#match-svg-' + q.id);
    const tiles = q.tiles, targets = q.targets;
    let resizeObs = null;

    function tileEl(id) { return box.querySelector(`[data-tile="${id}"]`); }
    function targetEl(id) { return box.querySelector(`[data-target="${id}"]`); }

    // 在图块与目标之间绘制黑色实线（端点对准各自中心）
    function drawLine(tileId, targetId) {
      const t = tileEl(tileId);
      const g = targetEl(targetId);
      if (!t || !g) return null;
      const br = box.getBoundingClientRect();
      const tr = t.getBoundingClientRect();
      const gr = g.getBoundingClientRect();
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      // 从图块右缘连到目标左缘，避免被卡片遮挡
      line.setAttribute('x1', tr.right - br.left);
      line.setAttribute('y1', tr.top + tr.height / 2 - br.top);
      line.setAttribute('x2', gr.left - br.left);
      line.setAttribute('y2', gr.top + gr.height / 2 - br.top);
      line.setAttribute('stroke', '#000000');
      line.setAttribute('stroke-width', '3');
      line.setAttribute('stroke-linecap', 'round');
      return line;
    }

    function redrawLines() {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      Object.keys(links).forEach((tileId) => {
        const line = drawLine(tileId, links[tileId]);
        if (line) svg.appendChild(line);
      });
    }

    function refreshMatch() {
      box.querySelectorAll('[data-tile]').forEach((el) => {
        const id = el.dataset.tile;
        el.classList.toggle('linked', links[id] != null);
        el.classList.toggle('pick', picked === id);
      });
      box.querySelectorAll('[data-target]').forEach((el) => {
        const id = el.dataset.target;
        el.classList.toggle('linked-target', Object.values(links).includes(id));
      });
      matchReady = tiles.every((t) => links[t.id] != null);
      redrawLines();
    }

    function persist() {
      const d = loadDraft('pra');
      d[q.id] = links;
      saveDraft('pra', d);
    }

    box.querySelectorAll('[data-tile]').forEach((el) => {
      el.addEventListener('click', () => {
        picked = el.dataset.tile; // 点另一个图块即切换选中
        refreshMatch();
      });
    });
    box.querySelectorAll('[data-target]').forEach((el) => {
      el.addEventListener('click', () => {
        if (picked == null) { toast('请先点击左边的图块'); return; }
        const tid = el.dataset.target;
        // 清除其它图块已连到该目标的线（一个方向只连一个图块）
        Object.keys(links).forEach((k) => { if (links[k] === tid) delete links[k]; });
        links[picked] = tid; // 已连的图块再次操作即更新
        persist();
        picked = null;
        refreshMatch();
        const done = praDone(q);
        if (!done) {
          if (matchReady) { praSubmitReady = () => submitPraMatch(q); refreshSubmitBar('pra'); }
          else { praSubmitReady = null; hideSubmitBar(); }
        }
      });
    });

    // 布局完成后绘制，并在尺寸变化/字体加载后重绘，保证端点对准
    requestAnimationFrame(() => refreshMatch());
    if (typeof ResizeObserver !== 'undefined') {
      resizeObs = new ResizeObserver(() => redrawLines());
      resizeObs.observe(box);
    }
    window.addEventListener('resize', redrawLines);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => redrawLines());
  }

  async function submitPraMatch(q) {
    const d = loadDraft('pra');
    try {
      const r = await apiPost('/api/submit', { type: 'submit_pra', sid: me.sid, name: me.name, group: me.group, qid: q.id, v: d[q.id], duration: 0 });
      await fetchMySubs();
      if (r && r.correct === true) {
        markPraPassed(q.id);
        praisePop(pickPraise(PRA_RIGHT), true); // 答对：表扬 + 冻结本题
        hideSubmitBar();
      } else if (r && r.correct === false) {
        praisePop(pickPraise(PRA_WRONG), false); // 答错：鼓励 + 不冻结，允许改连线再交
      } else {
        toast('✅ 已提交本题');
        hideSubmitBar();
      }
      renderPra();
    } catch (e) { toast('提交失败'); }
  }

  /* 媒体题 */
  function loadMediaDraft(qid) {
    const d = loadDraft('pra')[qid];
    if (d && typeof d === 'object' && (d.img !== undefined || d.audio !== undefined)) return d;
    return {};
  }
  let recorder = null, recChunks = [];
  function initMediaBox(q, root, donePhrase) {
    const media = loadMediaDraft(q.id);
    const camInput = root.querySelector('#camInput');
    root.querySelector('#camBtn').addEventListener('click', () => { camInput.click(); });
    camInput.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        const d = loadDraft('pra');
        if (!d[q.id] || typeof d[q.id] !== 'object') d[q.id] = {};
        d[q.id].img = reader.result;
        saveDraft('pra', d);
        root.querySelector('#camPreviewArea').innerHTML = `<img class="capture-preview" src="${reader.result}"/>`;
        root.querySelector('#camBtn').textContent = '✅ 已拍照';
        root.querySelector('#camBtn').classList.add('done');
        readyMedia(q, root, donePhrase);
      };
      reader.readAsDataURL(file);
    });

    root.querySelector('#recBtn').addEventListener('click', async () => {
      if (recorder) { recorder.stop(); return; }
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        recorder = new MediaRecorder(stream);
        recChunks = [];
        recorder.ondataavailable = (ev) => { if (ev.data.size) recChunks.push(ev.data); };
        recorder.onstop = () => {
          stream.getTracks().forEach((t) => t.stop());
          recorder = null;
          const blob = new Blob(recChunks, { type: 'audio/webm' });
          const reader = new FileReader();
          reader.onload = () => {
            const d = loadDraft('pra');
            if (!d[q.id] || typeof d[q.id] !== 'object') d[q.id] = {};
            d[q.id].audio = reader.result;
            saveDraft('pra', d);
            root.querySelector('#audioArea').innerHTML = `<audio controls src="${reader.result}"></audio>`;
            root.querySelector('#recBtn').textContent = '🔊 已录音';
            root.querySelector('#recBtn').classList.add('done');
            root.querySelector('#recStamp').classList.add('hidden');
            readyMedia(q, root, donePhrase);
          };
          reader.readAsDataURL(blob);
        };
        recorder.start();
        root.querySelector('#recStamp').classList.remove('hidden');
        root.querySelector('#recBtn').textContent = '⏹ 停止录音';
      } catch (e) {
        toast('无法访问麦克风');
      }
    });

    readyMedia(q, root, donePhrase);
  }
  function readyMedia(q, root, donePhrase) {
    const media = loadMediaDraft(q.id);
    if (!donePhrase && (media.img || media.audio)) {
      praSubmitReady = () => submitMedia(q);
      refreshSubmitBar('pra');
    } else hideSubmitBar();
  }
  async function submitMedia(q) {
    const media = loadMediaDraft(q.id);
    try {
      await apiPost('/api/submit', { type: 'submit_pra', sid: me.sid, name: me.name, group: me.group, qid: q.id, v: null, duration: 0 });
      if (media.img) await apiPost('/api/submit', { type: 'media_data', sid: me.sid, name: me.name, group: me.group, qid: q.id, kind: 'img', data: media.img });
      if (media.audio) await apiPost('/api/submit', { type: 'media_data', sid: me.sid, name: me.name, group: me.group, qid: q.id, kind: 'audio', data: media.audio, duration: 0 });
      toast('✅ 作品已上传');
      hideSubmitBar();
      praSubmitReady = null;
      await fetchMySubs();
      // 关键：只重绘“当前题（第5题）”视图，绝不切换 tab、不改 praOpenIdx。
      // 重绘后显示“✅ 已提交 ✓”，并立即刷新视图签名基线，
      // 防止下一次 5 秒轮询因签名包含 media 记录而再次 renderPra、把视图重置到其它题。
      renderPra();
      lastViewSig = viewSigOf();
    } catch (e) { toast('上传失败'); }
  }

  /* ---------- 自我评价 ---------- */
  function renderSelf() {
    const root = $('view-self');
    if (!state || !state.gate.selfOpen) { renderWait('self'); return; }
    const done = meSubs.some((s) => s.type === 'self');
    const mine = meSubs.find((s) => s.type === 'self');
    // 已生成的评价（提交成功后由后端返回，缓存在 localStorage）
    const savedEval = loadDraft('selfEval');
    const hasEval = done && savedEval && savedEval.text;
    const pickedCode = done && mine ? String(mine.answer) : selfPicked;

    let html = `<div class="card" id="selfCard"><h2>⭐ 自我评价</h2>
      <div class="sub">${done ? '你已完成今天的自我评价 ✓' : '看看今天自己的表现，点亮对应的星星后，点「提交」。'}</div>
      <div class="stars-row">`;
    config.config.self.forEach(([code, label, text]) => {
      const stars = Number(code.replace(/\D/g, '')) || 3;
      const sel = pickedCode != null && String(pickedCode) === String(code);
      const starStr = '★'.repeat(stars) + '☆'.repeat(5 - stars);
      html += `<div class="star-card ${sel ? 'sel' : ''}" data-code="${code}" ${done ? 'data-frozen="1"' : ''}>
        <div class="sc-stars">${starStr}</div>
        <div><b>${label}</b><div class="sc-text">${text}</div></div></div>`;
    });
    html += `</div>`;

    if (!done) {
      html += `<div class="self-actions">
        <button class="btn-primary" id="selfSubmitBtn" type="button">提交</button>
      </div>`;
    }
    html += `<div id="selfResult"></div>`;
    html += `</div>`;
    root.innerHTML = html;

    if (done) {
      // 已提交：完整展示评价（先成功提示再生成的过程不再重复，直接展示最终评价）
      if (hasEval) renderEvaluation(savedEval, false);
      return;
    }

    root.querySelectorAll('.star-card').forEach((el) => {
      el.addEventListener('click', () => {
        if (el.hasAttribute('data-frozen')) return;
        selfPicked = el.dataset.code; // 仅选中，不立即提交
        root.querySelectorAll('.star-card').forEach((x) =>
          x.classList.toggle('sel', x.dataset.code === selfPicked));
      });
    });

    root.querySelector('#selfSubmitBtn').addEventListener('click', () => {
      if (selfPicked == null) { toast('请先选择星级'); return; }
      submitSelf(selfPicked, root);
    });
  }

  function submitSelf(code, root) {
    const btn = root.querySelector('#selfSubmitBtn');
    btn.disabled = true;
    selfBusy = true;
    root.querySelectorAll('.star-card').forEach((el) => el.setAttribute('data-frozen', '1'));
    const result = root.querySelector('#selfResult');
    // 1) 成功提示
    result.innerHTML = `<div class="self-success">✅ 提交成功！小奇正在综合你的课堂练习表现，为你生成课堂评价：
      <div class="self-loading"><span class="spin"></span> 小奇正在生成中…</div></div>`;
    apiPost('/api/submit', { type: 'submit_self', sid: me.sid, name: me.name, group: me.group, v: code })
      .then(async (r) => {
        selfPicked = null;
        await fetchMySubs();
        // 2) 停顿约 1 秒，体现“正在生成”
        setTimeout(() => {
          const evaluation = r.evaluation || buildFallbackEvaluation(code);
          saveDraft('selfEval', evaluation);
          selfBusy = false;
          renderEvaluation(evaluation, true);
        }, 1000);
      })
      .catch(() => {
        selfBusy = false;
        btn.disabled = false;
        root.querySelectorAll('.star-card').forEach((el) => el.removeAttribute('data-frozen'));
        result.innerHTML = '';
        toast('提交失败，请重试');
      });
  }

  // 展示评价（我选的星级 + 档位标题 + 小奇 AI 评价 + 引导完成课后作业）
  function renderEvaluation(evaluation, animate) {
    const wrap = document.getElementById('selfResult');
    if (!wrap || !evaluation) return;
    const selfStar = Number(evaluation.selfStar) || 0;
    const starLine = selfStar > 0
      ? `<div class="self-eval-stars">我选的星级：<b>${'★'.repeat(selfStar)}${'☆'.repeat(5 - selfStar)}</b></div>`
      : '';
    wrap.innerHTML = `<div class="self-eval ${animate ? 'pop' : ''}">
      <div class="self-eval-badge">${evaluation.levelName || '课堂评价'}</div>
      ${starLine}
      <div class="self-eval-ai">🤖 小奇 AI 评价</div>
      <p class="self-eval-text">${evaluation.text || ''}</p>
      <div class="self-actions"><button class="btn-primary" id="goHwBtn" type="button">📚 去完成课后作业</button></div></div>`;
    const btn = wrap.querySelector('#goHwBtn');
    if (btn) btn.addEventListener('click', () => switchTab('hw')); // 未发布时作业 Tab 显示原等待页
  }

  // 极端情况下（旧后端未返回 evaluation）按本地计分兜底，口径与后端一致（含自评星级对比文案）
  const AI_EVAL_TEMPLATES_LOCAL = {
    high: '你给自己的评价很高，但练习中能看出，辨认图形时还容易出错。我们先扎实做好基础辨认，再慢慢关注细节、练习想象。',
    low: '你的答题表现很不错，能辨认图形、观察细节，甚至能想象物体样子，比你自评的水平更高。相信你对自己更有信心，继续大胆尝试。',
    match5: '你不仅可以辨认图形、细心对比观察，还能根据平面图形想象出物体完整的样子，空间想象能力很棒！继续保持，你可以尝试更有难度的观察挑战。',
    match4: '你能辨认不同视角的图形，还懂得对比观察，能关注物体表面的颜色和图案细节，观察很细心。接下来可以尝试看着平面图形，想一想物体完整的模样，挑战五星目标。',
    match3: '你已经学会从前面、右面、上面观察物体，能够认出不同方向看到的图形，顺利完成基础目标。可以多试一试，观察时留意物体上的图案细节，继续挑战更高星级。',
  };
  function buildFallbackEvaluation(selfCode) {
    const latest = {};
    meSubs.forEach((s) => {
      // 与服务端同口径：每题只取第一次提交（重试改对不提升表现星级）
      if (s.type === 'pra' && s.qid && s.correct !== null && !(s.qid in latest)) latest[s.qid] = s;
    });
    const qids = Object.keys(latest);
    const total = qids.length;
    const right = qids.filter((q) => latest[q].correct === true).length;
    // 表现星级：全对 5；答对≥一半 4；少于一半或无记录 3
    let perfStar = 3;
    if (total > 0 && right === total) perfStar = 5;
    else if (total > 0 && right >= Math.ceil(total / 2)) perfStar = 4;
    const level = perfStar === 5 ? 'excellent' : perfStar === 4 ? 'improving' : 'basic';
    const selfStar = selfCode === 's5' ? 5 : selfCode === 's4' ? 4 : selfCode === 's3' ? 3 : perfStar;
    const mismatch = selfStar > perfStar ? 'high' : selfStar < perfStar ? 'low' : null;
    const text = mismatch === 'high'
      ? AI_EVAL_TEMPLATES_LOCAL.high
      : mismatch === 'low'
        ? AI_EVAL_TEMPLATES_LOCAL.low
        : AI_EVAL_TEMPLATES_LOCAL['match' + perfStar];
    return {
      selfStar,
      perfStar,
      mismatch,
      level,
      levelName: { excellent: '勇攀高峰版', improving: '稳步提升版', basic: '夯实基础版' }[level],
      text,
      accuracy: total ? right / total : null,
      total,
    };
  }

  /* ---------- 课后作业（hwPool 题库随机抽题） ---------- */
  let hwAllDone = false;
  let hwCurrent = { level: null, qs: [] }; // 当前层级与抽到的题（提交条回调用）

  // 当前抽题签名：换题/重抽后变化，旧草稿随之失效
  function hwDraftSig(level) {
    const ids = state && state.hwDraft && Array.isArray(state.hwDraft[level]) ? state.hwDraft[level] : [];
    return level + ':' + ids.join(',');
  }
  function loadHwDraft(sig) {
    const d = loadDraft('hw');
    if (!d || d._sig !== sig || !d.v || typeof d.v !== 'object') return { _sig: sig, v: {} };
    return d;
  }
  function saveHwDraft(d) { saveDraft('hw', d); }

  // 从题库取出本层抽到的题（保持 hwDraft 顺序）
  function hwQuestions(level) {
    const pool = (config.config.hwPool && config.config.hwPool[level]) || [];
    const ids = state && state.hwDraft && Array.isArray(state.hwDraft[level]) ? state.hwDraft[level] : [];
    return ids.map((id) => pool.find((q) => String(q.id) === String(id))).filter(Boolean);
  }
  // 本人作业提交记录：每题取最新一条（meSubs 按时间升序，覆盖即最新）
  function hwDoneMap() {
    const m = {};
    meSubs.forEach((s) => { if (s.type === 'hw' && s.qid) m[s.qid] = s; });
    return m;
  }
  function hwAnswered(q, ans) {
    if (ans == null) return false;
    if (q.kind === 'choice') return Number.isInteger(ans);
    if (q.kind === 'viewlink') return Array.isArray(ans) && ans.length === 3 && ans.every((x) => !!x);
    if (q.kind === 'match3') return typeof ans === 'object' && !Array.isArray(ans) && Object.keys(ans).length >= 3;
    return false;
  }

  function renderHw() {
    const root = $('view-hw');
    if (!state || !state.hwPublished) { renderWait('hw'); return; }
    // 发布瞬间在线的学生：先显示约 3 秒“小奇生成中”过渡卡片，再自动出现分层作业
    if (hwGenerating) {
      if (Date.now() - hwGenAt < 3000) {
        root.innerHTML = `<div class="card wait"><div class="big hw-gen-emoji">⏳</div><p>小朋友们，请耐心等待，小奇正在为你生成个性化作业~</p></div>`;
        hideSubmitBar();
        if (!hwGenTimer) {
          hwGenTimer = setTimeout(() => {
            hwGenTimer = null;
            if (current === 'hw') renderHw();
          }, 3000);
        }
        return;
      }
      hwGenerating = false; // 超过 3 秒：落回正常渲染（无题时显示准备中卡片）
    }
    const acc = accuracyOf(meSubs, me.sid);
    const level = levelByAccuracy(acc);
    const hwMeta = (config.config.homework || {})[level] || {};
    const qs = hwQuestions(level);
    hwCurrent = { level, qs };
    if (qs.length === 0) {
      root.innerHTML = `<div class="card wait"><div class="big">⏳</div><p><b>课后作业</b> 准备中<br/>老师正在抽题，请稍候刷新查看～</p></div>`;
      hideSubmitBar();
      return;
    }
    const sig = hwDraftSig(level);
    const draft = loadHwDraft(sig);
    const done = hwDoneMap();
    const accText = acc == null ? '完成课前小测与课堂练习后自动分层' : `你本课正确率 ${Math.round(acc * 100)}% · 为你分配 ${level} 层作业`;

    let html = `<div class="card"><h2>📚 课后作业</h2><div class="sub">${accText}，共 ${qs.length} 题，全部作答后点底部「提交作业」。</div>`;
    html += `<div class="hw-title" style="background:${hwMeta.color || 'var(--blue)'}">${hwMeta.title || (level + ' 层作业')}</div>`;
    qs.forEach((q, i) => {
      const rec = done[q.id];
      const ans = rec ? rec.answer : draft.v[q.id];
      const verdict = rec
        ? (rec.correct === true
          ? '<span class="hw-verdict ok">已提交 ✓ 答对</span>'
          : '<span class="hw-verdict no">已提交 ✓ 答错</span>')
        : '';
      html += `<div class="hw-item ${rec ? 'frozen' : ''}" id="hw-item-${q.id}">`;
      html += `<div class="h-stem">${i + 1}. ${q.stem || ''}${verdict}</div>`;
      if (q.img) html += `<img class="q-img" src="${q.img}" alt="题目图"/>`;
      if (q.kind === 'choice') {
        html += `<div class="opts v3" id="hw-opt-${q.id}">` + (q.opts || []).map((o, idx) =>
          `<div class="opt ${Number(ans) === idx && ans != null ? 'sel' : ''}" data-v="${idx}"><div class="txt">${o}</div></div>`
        ).join('') + `</div>`;
      } else if (q.kind === 'viewlink') {
        const dirs = [['front', '前面'], ['right', '右面'], ['top', '上面']];
        html += `<div class="q-banner">图中从左到右 3 幅小图，分别是从哪个方向看到的？（三个方向不重复）</div>`;
        html += `<div class="hw-vlink" id="hw-vlink-${q.id}">`;
        for (let r = 0; r < 3; r += 1) {
          html += `<div class="hw-vrow" data-row="${r}"><span class="hw-vlabel">第 ${r + 1} 幅图</span>`;
          dirs.forEach(([dv, dl]) => {
            const on = Array.isArray(ans) && ans[r] === dv;
            html += `<button type="button" class="hw-vbtn ${on ? 'sel' : ''}" data-d="${dv}" ${rec ? 'disabled' : ''}>${dl}</button>`;
          });
          html += `</div>`;
        }
        html += `</div>`;
      } else if (q.kind === 'match3') {
        html += `<div class="q-banner">先点左边一项，再点右边对应答案完成连线（可重选）</div>`;
        html += `<div class="match" id="hw-match-box-${q.id}">`;
        html += `<svg class="match-svg" id="hw-match-svg-${q.id}"></svg>`;
        html += `<div class="col">` + (q.tiles || []).map((t, ti) =>
          `<div class="m-item" data-tile="t${ti}"><div class="txt">${t}</div></div>`).join('') + `</div>`;
        html += `<div class="arrow">→</div>`;
        html += `<div class="col">` + (q.targets || []).map((t, ti) =>
          `<div class="m-item" data-target="g${ti}"><div class="txt">${t}</div></div>`).join('') + `</div>`;
        html += `</div>`;
      }
      html += `</div>`;
    });
    if (hwMeta.handon) html += `<div class="handon"><b>动手实践：</b>${hwMeta.handon}</div>`;
    html += `</div>`;
    root.innerHTML = html;

    // 绑定作答交互（已提交的题冻结，不可再改）
    qs.forEach((q) => {
      if (done[q.id]) {
        if (q.kind === 'match3') initHwMatchBox(q, root, true);
        return;
      }
      if (q.kind === 'choice') {
        root.querySelectorAll(`#hw-opt-${q.id} .opt`).forEach((o) => {
          o.addEventListener('click', () => {
            const v = Number(o.dataset.v);
            const d = loadHwDraft(hwDraftSig(level));
            d.v[q.id] = v;
            saveHwDraft(d);
            root.querySelectorAll(`#hw-opt-${q.id} .opt`).forEach((x) => x.classList.toggle('sel', Number(x.dataset.v) === v));
            checkHwAllDone();
          });
        });
      } else if (q.kind === 'viewlink') {
        initHwViewlink(q, root, level);
      } else if (q.kind === 'match3') {
        initHwMatchBox(q, root, false);
      }
    });
    checkHwAllDone();
  }

  // 三视图连线（按钮版）：每行选一个方向，已选方向在其余行禁用，保证互不重复
  function initHwViewlink(q, root, level) {
    const box = root.querySelector('#hw-vlink-' + q.id);
    const rows = [...box.querySelectorAll('.hw-vrow')];
    function refresh() {
      const d = loadHwDraft(hwDraftSig(level));
      const cur = Array.isArray(d.v[q.id]) ? d.v[q.id] : [null, null, null];
      rows.forEach((rowEl, r) => {
        rowEl.querySelectorAll('.hw-vbtn').forEach((btn) => {
          const dv = btn.dataset.d;
          const takenByOther = cur.some((x, i) => i !== r && x === dv);
          btn.classList.toggle('sel', cur[r] === dv);
          btn.disabled = takenByOther;
        });
      });
    }
    rows.forEach((rowEl, r) => {
      rowEl.querySelectorAll('.hw-vbtn').forEach((btn) => {
        btn.addEventListener('click', () => {
          const d = loadHwDraft(hwDraftSig(level));
          const cur = Array.isArray(d.v[q.id]) ? d.v[q.id].slice() : [null, null, null];
          cur[r] = btn.dataset.d;
          d.v[q.id] = cur;
          saveHwDraft(d);
          refresh();
          checkHwAllDone();
        });
      });
    });
    refresh();
  }

  // 3 对 3 连一连：复用课堂练习的点选连线交互（写作业草稿；readOnly 时仅按提交答案画线）
  function initHwMatchBox(q, root, readOnly) {
    let links = {};
    if (readOnly) {
      // 已提交：answer 为长度3数组（第 i 个 tile → target 下标），转回连线展示
      const rec = hwDoneMap()[q.id];
      const v = rec && Array.isArray(rec.answer) ? rec.answer : [];
      v.forEach((g, i) => { if (g != null && g !== '') links['t' + i] = 'g' + g; });
    } else {
      const d = loadHwDraft(hwDraftSig(hwCurrent.level));
      links = d.v[q.id] && typeof d.v[q.id] === 'object' && !Array.isArray(d.v[q.id]) ? { ...d.v[q.id] } : {};
    }
    let picked = null;
    const box = root.querySelector('#hw-match-box-' + q.id);
    const svg = root.querySelector('#hw-match-svg-' + q.id);

    function tileEl(id) { return box.querySelector(`[data-tile="${id}"]`); }
    function targetEl(id) { return box.querySelector(`[data-target="${id}"]`); }

    function drawLine(tileId, targetId) {
      const t = tileEl(tileId);
      const g = targetEl(targetId);
      if (!t || !g) return null;
      const br = box.getBoundingClientRect();
      const tr = t.getBoundingClientRect();
      const gr = g.getBoundingClientRect();
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', tr.right - br.left);
      line.setAttribute('y1', tr.top + tr.height / 2 - br.top);
      line.setAttribute('x2', gr.left - br.left);
      line.setAttribute('y2', gr.top + gr.height / 2 - br.top);
      line.setAttribute('stroke', '#000000');
      line.setAttribute('stroke-width', '3');
      line.setAttribute('stroke-linecap', 'round');
      return line;
    }
    function redrawLines() {
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      Object.keys(links).forEach((tileId) => {
        const line = drawLine(tileId, links[tileId]);
        if (line) svg.appendChild(line);
      });
    }
    function refreshMatch() {
      box.querySelectorAll('[data-tile]').forEach((el) => {
        const id = el.dataset.tile;
        el.classList.toggle('linked', links[id] != null);
        el.classList.toggle('pick', picked === id);
      });
      box.querySelectorAll('[data-target]').forEach((el) => {
        const id = el.dataset.target;
        el.classList.toggle('linked-target', Object.values(links).includes(id));
      });
      redrawLines();
    }
    if (!readOnly) {
      box.querySelectorAll('[data-tile]').forEach((el) => {
        el.addEventListener('click', () => { picked = el.dataset.tile; refreshMatch(); });
      });
      box.querySelectorAll('[data-target]').forEach((el) => {
        el.addEventListener('click', () => {
          if (picked == null) { toast('请先点击左边的一项'); return; }
          const tid = el.dataset.target;
          Object.keys(links).forEach((k) => { if (links[k] === tid) delete links[k]; });
          links[picked] = tid;
          picked = null;
          const d = loadHwDraft(hwDraftSig(hwCurrent.level));
          d.v[q.id] = links;
          saveHwDraft(d);
          refreshMatch();
          checkHwAllDone();
        });
      });
    }
    requestAnimationFrame(() => refreshMatch());
    if (typeof ResizeObserver !== 'undefined') {
      const ro = new ResizeObserver(() => redrawLines());
      ro.observe(box);
    }
    window.addEventListener('resize', redrawLines);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => redrawLines());
  }

  function checkHwAllDone() {
    if (!config || !state || !hwCurrent.level || hwCurrent.qs.length === 0) {
      hwAllDone = false;
    } else {
      const d = loadHwDraft(hwDraftSig(hwCurrent.level));
      const done = hwDoneMap();
      // 已提交的题直接视为完成；未提交的看草稿是否已作答
      hwAllDone = hwCurrent.qs.every((q) => done[q.id] || hwAnswered(q, d.v[q.id]));
    }
    if (current === 'hw') refreshSubmitBar('hw');
  }

  async function submitHw() {
    const { level, qs } = hwCurrent;
    const d = loadHwDraft(hwDraftSig(level));
    try {
      for (const q of qs) {
        let v = d.v[q.id];
        if (q.kind === 'match3') {
          // 连线草稿 {t0:'g1',...} → 长度3数组（第 i 个 tile → target 下标）
          v = (q.tiles || []).map((t, i) => Number(String(v['t' + i]).slice(1)));
        }
        // eslint-disable-next-line no-await-in-loop
        await apiPost('/api/submit', {
          type: 'submit_hw', sid: me.sid, name: me.name, group: me.group, level, qid: q.id, v,
        });
      }
      toast('✅ 作业已提交');
      hideSubmitBar();
      await fetchMySubs();
      renderHw();
    } catch (e) { toast('提交失败，请重试'); }
  }

  /* ---------- 底部提交条 ---------- */
  function showSubmitBar(info, btnText, cb) {
    $('submitBar').classList.remove('hidden');
    $('fbInfo').textContent = info;
    const btn = $('submitBtn');
    btn.textContent = btnText;
    btn.onclick = cb;
    padDock();
  }
  function hideSubmitBar() { $('submitBar').classList.add('hidden'); padDock(); }

  init();
})();